-- Create table
-- Sa PostgreSQL, gumamit ng double quote para ma-preserve
-- ang capitalization ng table at column names.
-- Kapag walang double quote, automatic itong nagiging lowercase.
CREATE TABLE IF NOT EXISTS "tblTransaction" (

    --"TransactionID" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    "TransactionID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Payment" DECIMAL(10,2),
    "SubTotal" DECIMAL(10,2),
    "PaymentMethod" TEXT
        DEFAULT 'Cash'
        CHECK ("PaymentMethod" IN ('Cash', 'GCash')),
    "DiscountType" TEXT
        DEFAULT 'Fixed'
        CHECK ("DiscountType" IN ('Fixed', 'Percentage')),
    "Discount" DECIMAL(10,2),
    "TransactionDate" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "CreatedBy" UUID
        REFERENCES auth.users(id)
        ON DELETE CASCADE
);


-- CREATE INDEX

CREATE INDEX IF NOT EXISTS "idx_tblTransaction_TransactionID"
ON "tblTransaction" ("TransactionID");
CREATE INDEX IF NOT EXISTS "idx_tblTransaction_TransacID"
ON "tblTransaction" ("TransactionID");
 

-- Enable Row Level Security (RLS)

-- Makaka-edit/delete lang ng item
-- kung kanino naka-assign

ALTER TABLE "tblTransaction"
ENABLE ROW LEVEL SECURITY;


-- Policy: Users can view all Transaction

CREATE POLICY "User can view all Transaction"

ON "tblTransaction"

FOR SELECT

USING (true);


-- Policy: Users can create Transaction

CREATE POLICY "User can create Transaction"

ON "tblTransaction"

FOR INSERT

WITH CHECK (auth.uid() = "CreatedBy");


-- Policy: User can update Transaction
-- that they created or assigned

CREATE POLICY "User can update Transaction that they created or assigned"

ON "tblTransaction"

FOR UPDATE

USING (
    auth.uid() = "CreatedBy"
)

WITH CHECK (
    auth.uid() = "CreatedBy"
);


-- Policy: Only creators can delete Transaction

CREATE POLICY "Only creators can delete Transaction"

ON "tblTransaction"

FOR DELETE

USING (auth.uid() = "CreatedBy");


-- Function to update timestamp

CREATE OR REPLACE FUNCTION update_TransactionDate()

RETURNS TRIGGER AS $$

BEGIN

    NEW."TransactionDate" = NOW();

    RETURN NEW;

END;

$$ LANGUAGE plpgsql;


-- Trigger

CREATE TRIGGER update_tblTransaction_TransactionDate

BEFORE UPDATE ON "tblTransaction"

FOR EACH ROW

EXECUTE FUNCTION update_TransactionDate();